import React from 'react';
import { ArrowLeft, ArrowRight } from '@hexa-ui/icons';

import { CarouselProps, itemsInViewBySize } from './Carousel.types';
import { StyledCarousel, CarouselGroup } from './Carousel.styles';
import { CarouselIndicator } from './components/CarouselIndicator';
import { CarouselAction } from './components/CarouselAction';

const IMAGE_DISTANCE_FROM_BOTTOM = 32;

export function Carousel({
  autoRotate = false,
  autoRotateInterval = 15_000,
  showArrows = true,
  size = 'xl',
  swipeable = true,
  children,
}: React.PropsWithChildren<CarouselProps>) {
  const cardsPerView = itemsInViewBySize[size];
  const childrenArray = React.Children.toArray(children);
  const controlsStyle = showArrows
    ? { top: `calc(50% - ${IMAGE_DISTANCE_FROM_BOTTOM / 2}px)` }
    : {};

  // eslint-disable-next-line max-params
  const groups = childrenArray.reduce<React.ReactNode[][]>((acc, child, index) => {
    const groupIndex = Math.floor(index / cardsPerView);
    acc[groupIndex] = (acc[groupIndex] || []).concat(child);
    return acc;
  }, []);

  return (
    <StyledCarousel
      renderIndicator={(onClick, isActive) => (
        <CarouselIndicator isActive={isActive} onClick={onClick} />
      )}
      renderArrowPrev={(onClick, showArrow) =>
        showArrow ? (
          <CarouselAction
            data-testid="carousel-action-prev"
            onClick={onClick}
            icon={ArrowLeft}
            css={{ ...controlsStyle, left: 0 }}
          />
        ) : null
      }
      renderArrowNext={(onClick, showArrow) =>
        showArrow ? (
          <CarouselAction
            data-testid="carousel-action-next"
            onClick={onClick}
            icon={ArrowRight}
            css={{ ...controlsStyle, right: 0 }}
          />
        ) : null
      }
      autoPlay={autoRotate}
      interval={autoRotateInterval}
      showArrows={showArrows && childrenArray.length > cardsPerView}
      swipeable={swipeable}
      emulateTouch={swipeable}
      showStatus={false}
      showThumbs={false}
      infiniteLoop
    >
      {groups.map((child, index) => (
        <CarouselGroup
          // eslint-disable-next-line react/no-array-index-key
          key={index}
          css={{ gridTemplateColumns: `repeat(${cardsPerView}, 1fr)` }}
          data-testid="carousel-group"
        >
          {child}
        </CarouselGroup>
      ))}
    </StyledCarousel>
  );
}
